     1	import { panelRows } from './diagramSidePanelLayout';
     2	import { alternativeSelections } from '../../core/presentation/diagramAlternative';
     3	import { getDiagramRevision } from '../../core/diagrams/diagramRevisionStore';
     4	import { projectSelectedDiagramRows } from '../../core/presentation/diagramRevisionProjection';
     5	import type { MappingGridDocument } from './mappingGrid';
     6	import { visibleContentLines, type DiagramContent } from '../../core/diagrams/diagramContent';
     7	import { layoutScene, measureContent, resolveScene, type Diagram, type GridBox, type LineGridScene, type ResolvedGridBox } from '../../core/diagrams/lineGrid';
     8	import type { MappingPocGridRect } from '../selection/mappingPoc';
     9	
    10	/** Presentation of one diagram instance; never part of its source content. */
    11	export interface DiagramViewState {
    12	  display?: 'regular' | 'diff';
    13	  baseRevisionId?: string;
    14	  contentRevisionId: string;
    15	  collapsedContentNodeIds: string[];
    16	  /** Logical identities also cover nodes introduced by a selected revision. */
    17	  collapsedNodeRefs?: string[];
    18	}
    19	export type DiagramViews = Record<string, DiagramViewState>;
    20	export function resolveDiagramContent(diagram: Diagram): DiagramContent { return diagram.content; }
    21	export function projectDiagramContent(content: DiagramContent, view?: DiagramViewState) {
    22	  const collapsed = view?.contentRevisionId === content.revisionId ? view.collapsedContentNodeIds : [];
    23	  const sourceLines = visibleContentLines(content, collapsed);
    24	  const rows = content.ascii.split('\n');
    25	  const rowByLine = new Map(sourceLines.map((line, row) => [line, row]));
    26	  return {
    27	    ascii: sourceLines.map(line => rows[line - 1]).join('\n'), sourceLines,
    28	    rowForLine: (line: number) => rowByLine.get(line),
    29	    lineForRow: (row: number) => sourceLines[row],
    30	    /** Presentation can span a folded subtree; membership stays in raw node IDs. */
    31	    selectionRect: (rect: MappingPocGridRect): MappingPocGridRect | undefined => {
    32	      const visible = sourceLines.filter(line => line >= rect.startLine && line <= rect.endLine);
    33	      if (!visible.length) return undefined;
    34	      return { ...rect, startLine: rowByLine.get(visible[0])! + 1, endLine: rowByLine.get(visible.at(-1)!)! + 1 };
    35	    },
    36	    /** Only exact, contiguous source regions can carry an editable selection. */
    37	    rect: (rect: MappingPocGridRect): MappingPocGridRect | undefined => {
    38	      const start = rowByLine.get(rect.startLine), end = rowByLine.get(rect.endLine);
    39	      if (start === undefined || end === undefined || end - start !== rect.endLine - rect.startLine) return undefined;
    40	      return { ...rect, startLine: start + 1, endLine: end + 1 };
    41	    }
    42	  };
    43	}
    44	export function diagramProjection(scene: LineGridScene, boxId: string, contentId: string, views?: DiagramViews) {
    45	  return projectDiagramContent(resolveDiagramContent(scene.contents[contentId]), views?.[`grid:${boxId}`]);
    46	}
    47	
    48	/** Folded bounds subtract hidden text cells while retaining any explicitly reserved extra space. */
    49	export function resolveDiagramView(scene: LineGridScene, views?: DiagramViews): ResolvedGridBox {
    50	  const resolved = resolveScene(scene);
    51	  if (!views || !Object.keys(views).length) return resolved;
    52	  const visit = (node: ResolvedGridBox): ResolvedGridBox => {
    53	    if (node.box.collapsed) return node;
    54	    if (node.contentId) {
    55	      if (selectedSceneContents.get(scene)?.has(node.contentId)) return node;
    56	      const content = scene.contents[node.contentId].content, view = views[`grid:${node.box.id}`];
    57	      if (view?.contentRevisionId !== content.revisionId || !view.collapsedContentNodeIds.length) return node;
    58	      const full = measureContent(content.ascii), visible = measureContent(projectDiagramContent(content, view).ascii);
    59	      return { ...node, bounds: { ...node.bounds,
    60	        columns: node.bounds.columns - full.columns + visible.columns,
    61	        rows: node.bounds.rows - full.rows + visible.rows } };
    62	    }
    63	    const children = node.children.map(visit);
    64	    return { ...node, children, bounds: { ...node.bounds,
    65	      columns: Math.max(1, node.box.minimumSize?.columns ?? 1, ...children.map(child => child.bounds.column - node.bounds.column + child.bounds.columns)),
    66	      rows: Math.max(1, node.box.minimumSize?.rows ?? 1, ...children.map(child => child.bounds.row - node.bounds.row + child.bounds.rows)) } };
    67	  };
    68	  return visit(resolved);
    69	}
    70	/** Prune deleted owners and revision-scoped IDs on every document mutation. */
    71	export function normalizeDiagramViews(scene: LineGridScene, views?: DiagramViews): DiagramViews | undefined {
    72	  if (!views || !Object.keys(views).length) return views;
    73	  const valid: DiagramViews = {};
    74	  const visit = (box: GridBox) => {
    75	    const key = `grid:${box.id}`, view = views[key];
    76	    if (box.kind === 'container') { box.children.forEach(visit); return; }
    77	    if (!view) return;
    78	    const content = resolveDiagramContent(scene.contents[box.contentId]);
    79	    if (content.revisionId !== view.contentRevisionId) return;
    80	    const nodes = content.structure.kind === 'tree' ? content.structure.nodes : {};
    81	    const ids = view.collapsedContentNodeIds.filter(id => Object.hasOwn(nodes, id) && nodes[id].childIds.length);
    82	    valid[key] = ids.length === view.collapsedContentNodeIds.length ? view : { ...view, collapsedContentNodeIds: ids };
    83	  };
    84	  visit(scene.root);
    85	  return Object.keys(valid).length === Object.keys(views).length && Object.keys(valid).every(key => valid[key] === views[key]) ? views : valid;
    86	}
