    88	const selectedScenes = new WeakMap<MappingGridDocument, LineGridScene>();
    89	const selectedSceneContents = new WeakMap<LineGridScene, ReadonlySet<string>>();
    90	/** Reserve composition bounds without changing the canvas document or its content bindings. */
    91	export function presentationScene(document: MappingGridDocument): LineGridScene {
