    47	  const ids = new Map(parsed.map(node => [node.line, `${revisionId}:${content.asciiSha256}:line-${node.line}`]));
    48	  const nodes: Record<string, DiagramContentNode> = {};
    49	  for (const node of parsed) {
    50	    const id = ids.get(node.line)!;
    51	    const peer = parsed.find(next => next.line > node.line && next.branchColumn <= node.branchColumn);
    52	    nodes[id] = { id, label: node.text, line: node.line, branchColumn: node.branchColumn, startColumn: node.textColumn,
    53	      endColumn: node.textColumn + Math.max(1, node.text.length) - 1,
    54	      parentId: node.parentLine === undefined ? undefined : ids.get(node.parentLine),
    55	      childIds: parsed.filter(child => child.parentLine === node.line).map(child => ids.get(child.line)!),
    56	      foldRanges: node.descendantLines.length ? [{ startLine: node.line + 1, endLine: peer ? peer.line - 1 : ascii.split('\n').length }] : [] };
    57	  }
    58	  return { ...content, structure: { kind: 'tree', parserVersion: treeVersion, rootIds: Object.values(nodes).filter(node => !node.parentId).map(node => node.id), nodes } };
    59	}
    60	export function visibleContentLines(content: DiagramContent, collapsedIds: readonly string[]): number[] {
    61	  const hidden = new Set<number>();
    62	  if (content.structure.kind === 'tree') for (const id of collapsedIds) {
    63	    const node = content.structure.nodes[id];
    64	    if (!node) throw new Error('STALE_CONTENT_NODE');
    65	    for (const range of node.foldRanges) for (let line = range.startLine; line <= range.endLine; line++) hidden.add(line);
    66	  }
    67	  return content.ascii.split('\n').map((_, i) => i + 1).filter(line => !hidden.has(line));
    68	}
    69	
    70	export function contentTreeNodes(content: DiagramContent): import('./asciiTree').AsciiTreeNode[] {
    71	  if (content.structure.kind !== 'tree') return [];
    72	  const nodes = content.structure.nodes;
    73	  return Object.values(nodes).map(node => ({ line: node.line, branchColumn: node.branchColumn, textColumn: node.startColumn, text: node.label,
    74	    parentLine: node.parentId ? nodes[node.parentId]?.line : undefined,
    75	    descendantLines: Object.values(nodes).filter(child => node.foldRanges.some(range => child.line >= range.startLine && child.line <= range.endLine)).map(child => child.line) }));
    76	}
