    19	export interface ProjectionSelectionResult {
    20	  ascii: string;
    21	  matchedSourceEvidenceIds: string[];
    22	  unmatchedSourceEvidenceIds: string[];
    23	  targetNodeIds: string[];
    24	  visibleNodeIds: string[];
    25	  /** Matched subtrees only, excluding ancestors added solely for display. */
    26	  projectedNodeIds: string[];
