    30	
    31	function record(value: unknown, label: string): asserts value is Record<string, unknown> {
    32	  if (!value || typeof value !== "object" || Array.isArray(value)) {
    33	    throw new Error(`${label} must be an object`);
    34	  }
    35	}
    36	
    37	function id(value: unknown, label: string): asserts value is string {
    38	  if (typeof value !== "string" || !value.trim() || value !== value.trim()) {
    39	    throw new Error(`${label} must be a nonempty string without surrounding whitespace`);
    40	  }
    41	  if (value === "__proto__" || value === "constructor" || value === "prototype") {
    42	    throw new Error(`${label} contains a reserved identifier`);
    43	  }
    44	}
    45	
    46	function ids(value: unknown, label: string, nonempty = true): asserts value is string[] {
    47	  if (!Array.isArray(value) || (nonempty && value.length === 0)) {
    48	    throw new Error(`${label} must be ${nonempty ? "a nonempty" : "an"} array`);
    49	  }
    50	  for (const entry of value) id(entry, `${label} entry`);
    51	}
    52	
    53	function validateShape(projection: ProjectProjectionRecord): void {
    54	  record(projection, "projection");
    55	  for (const key of ["id", "projectId", "sourceRepresentationId", "sourceRevisionId",
    56	    "targetRepresentationId", "targetRevisionId"] as const) id(projection[key], key);
    57	  if (typeof projection.name !== "string" || !projection.name.trim()) {
    58	    throw new Error("projection name must be a nonempty string");
    59	  }
    60	  if (projection.match !== "any") throw new Error("projection match must be any");
    61	  if (!Array.isArray(projection.links) || projection.links.length === 0) {
    62	    throw new Error("projection links must be a nonempty array");
    63	  }
    64	  for (const link of projection.links) {
    65	    record(link, "projection link");
    66	    ids(link.sourceEvidenceIds, "sourceEvidenceIds");
    67	    ids(link.targetNodeIds, "targetNodeIds");
    68	  }
    69	}
