    71	/**
    72	 * Structural identity is scoped to the immutable Project revision, never row coordinates.
    73	 * Conventional trees support a plain root with |, +--, \\--, and `-- connectors;
    74	 * legacy arrow branches remain supported. Other semantic lines are standalone
    75	 * roots, not implicit continuation children (matching the shared index grammar).
    76	 */
    77	export function buildProjectionTree(revision: ProjectRepresentationRevisionRecord): TreeRepresentationIndex {
    78	  record(revision, "target revision");
    79	  if (revision.representationKind !== "tree") throw new Error("projection target must be a tree");
    80	  id(revision.id, "target revision id");
    81	  id(revision.asciiSha256, "target ASCII hash");
    82	  if (typeof revision.ascii !== "string") throw new Error("target ASCII must be a string");
    83	  return buildTreeRepresentationIndex({
    84	    revision: { artifactId: revision.id, asciiSha256: revision.asciiSha256 },
    85	    ascii: revision.ascii,
    86	    codeEntityMap: {
    87	
    88	      artifactId: revision.id,
    89	      asciiSha256: revision.asciiSha256,
    90	
    91	      mappings: revision.mappings.map((mapping) => ({
    92	        id: mapping.id,
    93	        entityId: mapping.evidenceId,
    94	        sourceRangeId: mapping.sourceRangeId,
    95	        sourceRangeIndex: revision.evidence[mapping.evidenceId]?.sourceRanges
    96	          .findIndex((range) => range.id === mapping.sourceRangeId) ?? -1,
    97	        line: mapping.line,
    98	        startColumn: mapping.startColumn,
    99	        endColumn: mapping.endColumn
   100	      }))
   101	    }
   102	  });
   103	}
