   105	/** Reject cross-project, stale/foreign-revision, and unresolved mappings before persistence/use. */
   106	export function validateProjection(
   107	  projection: ProjectProjectionRecord,
   108	  catalog: ProjectRepresentationCatalogRecord
   109	): void {
   110	  validateShape(projection);
   111	  record(catalog, "representation catalog");
   112	  if (catalog.projectId !== projection.projectId) throw new Error("projection must belong to the same project");
   113	  record(catalog.representations, "catalog representations");
   114	  record(catalog.revisions, "catalog revisions");
   115	  for (const side of ["source", "target"] as const) {
   116	    const representationId = projection[`${side}RepresentationId`];
   117	    const revisionId = projection[`${side}RevisionId`];
   118	    const representation = Object.hasOwn(catalog.representations, representationId)
   119	      ? catalog.representations[representationId] : undefined;
   120	    const revision = Object.hasOwn(catalog.revisions, revisionId) ? catalog.revisions[revisionId] : undefined;
   121	    record(representation, `${side} representation`);
   122	    record(revision, `${side} revision`);
   123	    if (representation.id !== representationId || revision.id !== revisionId
   124	      || representation.projectId !== projection.projectId || revision.projectId !== projection.projectId) {
   125	      throw new Error(`${side} representation and revision must belong to the same project`);
   126	    }
   127	    if (revision.representationId !== representationId || !Array.isArray(representation.revisionIds)
   128	      || !representation.revisionIds.includes(revisionId)) {
   129	      throw new Error(`${side} revision is not owned by its representation`);
   130	    }
   131	    if (side === "target" && representation.representationKind !== "tree") {
   132	      throw new Error("projection target representation must be a tree");
   133	    }
   134	  }
   135	  const source = catalog.revisions[projection.sourceRevisionId];
   136	  record(source.evidence, "source evidence");
   137	  const target = buildProjectionTree(catalog.revisions[projection.targetRevisionId]);
   138	  if (projection.compactionProjection) validateCompactionProjection(projection.compactionProjection, new Set(Object.keys(target.nodes)));
   139	  for (const link of projection.links) {
   140	    for (const evidenceId of link.sourceEvidenceIds) {
   141	      if (!Object.hasOwn(source.evidence, evidenceId) || source.evidence[evidenceId]?.id !== evidenceId) {
   142	        throw new Error(`unknown source evidence: ${evidenceId}`);
   143	      }
   144	    }
   145	    for (const nodeId of link.targetNodeIds) {
   146	      if (!Object.hasOwn(target.nodes, nodeId)) throw new Error(`unknown target node: ${nodeId}`);
   147	    }
   148	  }
   149	}
   150	
   151	/**
   152	 * OR-match links, then include matched subtrees and their required ancestor paths.
   153	 * Evidence lists retain selection order; node lists retain original target pre-order.
   154	 * Every rendered row carries its original one-based source line; connectors are regenerated.
   155	 */
   156	export function projectSelection(
   157	  projection: ProjectProjectionRecord,
   158	  targetRevision: ProjectRepresentationRevisionRecord,
   159	  selectedEvidenceIds: readonly string[]
   160	): ProjectionSelectionResult {
   161	  validateShape(projection);
   162	  ids(selectedEvidenceIds, "selectedEvidenceIds", false);
   163	  record(targetRevision, "target revision");
   164	  if (targetRevision.id !== projection.targetRevisionId
   165	    || targetRevision.representationId !== projection.targetRepresentationId
   166	    || targetRevision.projectId !== projection.projectId) {
   167	    throw new Error("projection target revision does not match its pinned revision");
   168	  }
   169	  const tree = buildProjectionTree(targetRevision);
   170	  const selected = [...new Set(selectedEvidenceIds)];
   171	  const selectedSet = new Set(selected);
   172	  const matched = new Set<string>();
   173	  const targets = new Set<string>();
   174	  for (const link of projection.links) {
   175	    for (const nodeId of link.targetNodeIds) {
   176	      if (!Object.hasOwn(tree.nodes, nodeId)) throw new Error(`unknown target node: ${nodeId}`);
   177	    }
   178	    const matches = link.sourceEvidenceIds.filter((evidenceId) => selectedSet.has(evidenceId));
   179	    if (!matches.length) continue;
   180	    matches.forEach((evidenceId) => matched.add(evidenceId));
   181	    link.targetNodeIds.forEach((nodeId) => targets.add(nodeId));
   182	  }
   183	  const visible = new Set<string>();
   184	  const pending = [...targets];
   185	  while (pending.length) {
   186	    const nodeId = pending.pop()!;
   187	    if (visible.has(nodeId)) continue;
   188	    visible.add(nodeId);
   189	    pending.push(...tree.nodes[nodeId].childIds);
   190	  }
   191	  const projected = new Set(visible);
   192	  for (const nodeId of targets) {
   193	    let parentId = tree.nodes[nodeId].parentId;
   194	    while (parentId) {
   195	      visible.add(parentId);
   196	      parentId = tree.nodes[parentId].parentId;
   197	    }
   198	  }
   199	  const lines: string[] = [];
   200	  const rows: ProjectionSelectionResult["rows"] = [];
   201	  const render = (nodeId: string, prefix: string, connector: string, childPrefix: string): void => {
   202	    const node = tree.nodes[nodeId];
   203	    lines.push(prefix + connector + node.text);
   204	    rows.push({ nodeId, sourceLine: node.line });
   205	    const children = node.childIds.filter((childId) => visible.has(childId));
   206	    children.forEach((childId, index) => {
   207	      const last = index === children.length - 1;
   208	      render(childId, childPrefix, last ? "\\-- " : "+-- ", childPrefix + (last ? "    " : "|   "));
   209	    });
   210	  };

