    33	export function buildDiagramContent(ascii: string, revisionId: string, kind: 'diagram' | 'tree' = 'diagram', version?: DiagramParserVersion): DiagramContent {
    34	  const parserVersion = version ?? (kind === 'tree' ? 'ascii-tree-2' : 'ascii-graph-1');
    35	  if (kind === 'tree' && parserVersion !== 'ascii-tree-1' && parserVersion !== 'ascii-tree-2') throw new Error('Unknown tree parser version');
    36	  if (kind === 'diagram' && parserVersion !== 'ascii-graph-1' && parserVersion !== 'legacy-diagram') throw new Error('Unknown diagram parser version');
    37	  // A blank rectangular diagram reserves editable canvas space (e.g. a generated-diagram placeholder).
    38	  const lines = ascii.split('\n');
    39	  const blankRectangle = kind === 'diagram' && lines.length > 1 && lines[0].length > 0
    40	    && lines.every(line => line.length === lines[0].length && /^ +$/.test(line));
    41	  if ((!ascii.trim() && !blankRectangle) || ascii.length > 20000 || /[^\x20-\x7e\n]/.test(ascii)) throw new Error('Diagram must contain 1–20000 printable ASCII characters with LF newlines');
    42	  const content: DiagramContent = { revisionId, ascii, asciiSha256: asciiSha256(ascii),
    43	    structure: parserVersion === 'ascii-graph-1' ? { kind: 'diagram', parserVersion } : { kind: 'diagram' } };
    44	  if (kind === 'diagram') return content;
    45	  const treeVersion = parserVersion as 'ascii-tree-1' | 'ascii-tree-2';
    46	  const parsed = parseAsciiTree(ascii, treeVersion);
    47	  const ids = new Map(parsed.map(node => [node.line, `${revisionId}:${content.asciiSha256}:line-${node.line}`]));
    48	  const nodes: Record<string, DiagramContentNode> = {};
    49	  for (const node of parsed) {
    50	    const id = ids.get(node.line)!;
    51	    const peer = parsed.find(next => next.line > node.line && next.branchColumn <= node.branchColumn);
    52	    nodes[id] = { id, label: node.text, line: node.line, branchColumn: node.branchColumn, startColumn: node.textColumn,
    53	      endColumn: node.textColumn + Math.max(1, node.text.length) - 1,
    54	      parentId: node.parentLine === undefined ? undefined : ids.get(node.parentLine),
    55	      childIds: parsed.filter(child => child.parentLine === node.line).map(child => ids.get(child.line)!),
